WITH payload AS (SELECT '[{"id":"c8202611-05a0-4a9b-9f00-000000000001","title":"华文成语与表达大师","subject":"中文","grade_level":"Year 6","language":"zh","description":"20 道原创华文成语、修辞及表达题，适合小学高年级复习。","questions":[{"question":"“画蛇添足”最接近哪种意思？","options":["做多余的事反而坏事","认真完成工作","及时帮助别人","认真计划未来"],"correct_option_index":0,"explanation":"画好蛇后再添脚，反而破坏原有成果。"},{"question":"“守株待兔”提醒我们什么？","options":["要多种树","兔子跑得快","耐心总能成功","不能只凭侥幸等待收获"],"correct_option_index":3,"explanation":"寓言强调不主动努力而只等好运并不可取。"},{"question":"“井底之蛙”形容怎样的人？","options":["喜欢读书的人","乐于旅行的人","见识狭窄的人","善于游泳的人"],"correct_option_index":2,"explanation":"井底的青蛙看到的天空很小，表示眼界有限。"},{"question":"“雪中送炭”强调什么？","options":["事后表扬别人","在困难时给予及时帮助","在冬天卖木炭","雪地里玩耍"],"correct_option_index":1,"explanation":"最有价值的帮助往往发生在对方急需时。"},{"question":"“亡羊补牢”表达什么道理？","options":["发现错误后及时改正仍有意义","丢羊后不能补救","养羊必须建高墙","任何问题都要放弃"],"correct_option_index":0,"explanation":"寓言告诉我们发现漏洞后仍应及时补救。"},{"question":"“自相矛盾”指什么？","options":["两个意见都正确","做事特别迅速","表达十分清楚","说法前后互相冲突"],"correct_option_index":3,"explanation":"互相矛盾的主张不能同时成立。"},{"question":"“掩耳盗铃”比喻什么？","options":["沉着冷静","互相合作","自欺欺人","勤奋学习"],"correct_option_index":2,"explanation":"捂住耳朵不代表别人听不到铃声。"},{"question":"“刻舟求剑”讽刺哪种做法？","options":["保护重要物品","情况变了却仍用旧办法","计划周全","记录航行路线"],"correct_option_index":1,"explanation":"船在前进，落剑的位置不会跟着船上的记号走。"},{"question":"“一举两得”是什么意思？","options":["一次行动获得两种好处","只做一件事","两人一起行动","先失败再成功"],"correct_option_index":0,"explanation":"一个行动同时取得两个积极结果。"},{"question":"“心不在焉”的意思是？","options":["心情愉快","身体强壮","态度友善","注意力不集中"],"correct_option_index":3,"explanation":"心思没有放在正在做的事情上。"},{"question":"“废寝忘食”形容什么？","options":["睡眠充足","生活很规律","专心投入而忘记休息吃饭","讨厌所有食物"],"correct_option_index":2,"explanation":"通常用来形容对某件事投入程度很高。"},{"question":"“百折不挠”体现哪种品质？","options":["从不尝试新事物","遇到挫折仍坚持","随意更换目标","遇难马上逃避"],"correct_option_index":1,"explanation":"“不挠”表示遭遇困难也不轻易屈服。"},{"question":"“滥竽充数”形容什么？","options":["没有本领却混在行家中","乐于学习音乐","团队演奏出色","谦虚请教别人"],"correct_option_index":0,"explanation":"故事中的人不会吹竽，却假装加入乐队。"},{"question":"“胸有成竹”表示什么？","options":["胸前真的有竹子","喜欢画动物","做事全凭运气","做事前已有成熟计划"],"correct_option_index":3,"explanation":"原指画竹前心中已有竹子的形象。"},{"question":"“举一反三”指什么能力？","options":["同时做四件事","改变原来的答案","由一个例子推知相似情形","反复记一个答案"],"correct_option_index":2,"explanation":"理解规律后能迁移运用到类似问题。"},{"question":"“半途而废”的意思是？","options":["一边走路一边学习","事情进行到一半就放弃","提前完成工作","顺利到达终点"],"correct_option_index":1,"explanation":"强调未完成目标就中途停止。"},{"question":"“聚精会神”形容什么？","options":["注意力非常集中","精神疲倦","四处张望","感到害怕"],"correct_option_index":0,"explanation":"“聚”与“会”都加强专注的意思。"},{"question":"“耳濡目染”强调哪种影响？","options":["只靠听力学习","视力得到改善","一次听课就精通","长期接触而受到潜移默化的影响"],"correct_option_index":3,"explanation":"经常听到、看到某事会逐渐受其影响。"},{"question":"“循序渐进”的学习方法是？","options":["每天更换全部教材","只背答案不理解","按照次序逐步提高","跳过基础直接挑战最难题"],"correct_option_index":2,"explanation":"循序渐进强调从基础到复杂、逐步学习。"},{"question":"“同舟共济”适合描述什么场景？","options":["不愿分享信息","大家合作面对困难","每人独自解决所有问题","在船上争吵"],"correct_option_index":1,"explanation":"同乘一船渡河，比喻齐心协力。"}]},{"id":"c8202611-05a0-4a9b-9f00-000000000002","title":"华文语文与阅读思考","subject":"中文","grade_level":"Year 6","language":"zh","description":"20 道标点、句型、词义及阅读理解基础题。","questions":[{"question":"“天空像一块蓝色的画布。”用了什么修辞手法？","options":["反问","设问","排比","比喻"],"correct_option_index":3,"explanation":"“像”把天空比作蓝色画布，是比喻。"},{"question":"“风轻轻地抚摸着树叶。”用了什么修辞手法？","options":["反问","引用","拟人","夸张"],"correct_option_index":2,"explanation":"让风做出人的动作“抚摸”，属于拟人。"},{"question":"哪个句子使用了疑问句？","options":["今天下雨了。","你今天带雨伞了吗？","请带雨伞。","天气真好！"],"correct_option_index":1,"explanation":"疑问句用来提出问题，常以问号结尾。"},{"question":"哪个词语与“勤奋”意思最接近？","options":["努力","懒散","犹豫","粗心"],"correct_option_index":0,"explanation":"勤奋强调认真努力地学习或工作。"},{"question":"“宽阔”的反义词是什么？","options":["辽阔","广大","平坦","狭窄"],"correct_option_index":3,"explanation":"宽阔与狭窄描述空间大小的相反特征。"},{"question":"“因为下雨，所以比赛延期了。”表示什么关系？","options":["假设关系","转折关系","因果关系","并列关系"],"correct_option_index":2,"explanation":"“因为……所以……”连接原因与结果。"},{"question":"“虽然很累，但她仍坚持练习。”表达什么关系？","options":["选择关系","转折关系","因果关系","递进关系"],"correct_option_index":1,"explanation":"“虽然……但……”前后语义有转折。"},{"question":"哪个标点符号用来表示直接问句结束？","options":["问号（？）","句号（。）","逗号（，）","顿号（、）"],"correct_option_index":0,"explanation":"完整的直接疑问句通常用问号。"},{"question":"下列哪组词语是近义词？","options":["高兴—难过","宽阔—狭窄","开始—结束","迅速—快速"],"correct_option_index":3,"explanation":"迅速和快速都表示速度快。"},{"question":"下列哪组词语是反义词？","options":["美丽—漂亮","勇敢—英勇","明亮—昏暗","安静—宁静"],"correct_option_index":2,"explanation":"明亮与昏暗表示光线的相反状态。"},{"question":"“书是知识的钥匙。”中的“钥匙”是什么用法？","options":["拟声词","比喻性的说法","真实开门工具","量词"],"correct_option_index":1,"explanation":"这里把书比作打开知识大门的工具。"},{"question":"“他小心翼翼地放下玻璃杯。”哪个词形容动作态度？","options":["小心翼翼","玻璃杯","放下","他"],"correct_option_index":0,"explanation":"“小心翼翼”描述动作非常谨慎。"},{"question":"写观察日记时最重要的是什么？","options":["编造有趣的结果","只写标题","省略时间和地点","如实记录观察到的现象"],"correct_option_index":3,"explanation":"观察日记应以真实观察为基础。"},{"question":"阅读说明文时，想快速找日期应先做什么？","options":["只读最后一句","忽略所有数字","寻找与日期有关的关键词","逐字背诵全文"],"correct_option_index":2,"explanation":"扫读并抓关键词可以更快定位信息。"},{"question":"“如果明天晴天，我们就去郊游。”是什么关系？","options":["转折关系","条件关系","因果关系","并列关系"],"correct_option_index":1,"explanation":"“如果……就……”说明满足条件才会发生的事情。"},{"question":"下列哪个句子更适合作为正式邀请？","options":["诚邀您参加本周五的交流活动。","快点过来啦！","你必须出现哦！","来嘛，不来不行！"],"correct_option_index":0,"explanation":"正式邀请应礼貌、清晰并说明活动。"},{"question":"写故事时“人物、时间、地点”主要帮助读者了解什么？","options":["答案选项","拼音声调","广告价格","故事背景"],"correct_option_index":3,"explanation":"这三项交代故事发生的基本背景。"},{"question":"“他把一杯水递给口渴的同学。”可以推断他怎么样？","options":["只关心自己","不喜欢水","乐于帮助别人","不愿与人合作"],"correct_option_index":2,"explanation":"主动给口渴的同学水体现关心。"},{"question":"哪一个是正确的量词搭配？","options":["一把天空","一条河","一只书","一本马"],"correct_option_index":1,"explanation":"“河”常用量词“条”。"},{"question":"要判断一篇文章的中心思想，最适合怎么做？","options":["归纳全文反复强调的主要意思","只看第一个生字","计算标点总数","只读标题的最后一个字"],"correct_option_index":0,"explanation":"中心思想需要结合全文内容综合判断。"}]},{"id":"c8202611-05a0-4a9b-9f00-000000000003","title":"Bahasa Melayu: Perbendaharaan Kata","subject":"Bahasa Melayu","grade_level":"Tahun 6","language":"ms","description":"20 soalan kosa kata dan makna perkataan dengan penerangan ringkas.","questions":[{"question":"Apakah kata seerti bagi “gembira”?","options":["marah","penat","riang","sedih"],"correct_option_index":2,"explanation":"Gembira dan riang membawa maksud perasaan suka."},{"question":"Apakah kata lawan bagi “tinggi”?","options":["kuat","rendah","panjang","besar"],"correct_option_index":1,"explanation":"Tinggi dan rendah menunjukkan ukuran ketinggian yang bertentangan."},{"question":"Apakah maksud “rajin”?","options":["tekun melakukan kerja","suka bertangguh","mudah lupa","tidak mengambil peduli"],"correct_option_index":0,"explanation":"Rajin bermaksud bersungguh-sungguh menjalankan tugas."},{"question":"Apakah kata seerti bagi “cepat”?","options":["lambat","senyap","berat","pantas"],"correct_option_index":3,"explanation":"Cepat dan pantas merujuk kepada kelajuan tinggi."},{"question":"Apakah kata lawan bagi “bersih”?","options":["cantik","wangi","kotor","kemas"],"correct_option_index":2,"explanation":"Bersih bertentangan dengan kotor."},{"question":"Apakah maksud “berjimat”?","options":["berbelanja tanpa had","menggunakan wang dengan cermat","membeli semua barang","membuang makanan"],"correct_option_index":1,"explanation":"Berjimat bermaksud tidak membazir sumber atau wang."},{"question":"Apakah kata seerti bagi “bijak”?","options":["pandai","cuai","malas","lemah"],"correct_option_index":0,"explanation":"Bijak dan pandai menggambarkan keupayaan berfikir dengan baik."},{"question":"Apakah kata lawan bagi “gelap”?","options":["suram","malam","kelam","terang"],"correct_option_index":3,"explanation":"Gelap dan terang bertentangan dari segi cahaya."},{"question":"Apakah maksud “berhemah”?","options":["bertindak melulu","suka membazir","berkelakuan sopan","bercakap kasar"],"correct_option_index":2,"explanation":"Berhemah menunjukkan tingkah laku yang tertib dan sopan."},{"question":"Apakah kata seerti bagi “damai”?","options":["marah","aman","bising","cemas"],"correct_option_index":1,"explanation":"Damai dan aman merujuk kepada keadaan tenteram."},{"question":"Apakah kata lawan bagi “sempit”?","options":["luas","kecil","pendek","nipis"],"correct_option_index":0,"explanation":"Sempit dan luas menggambarkan keluasan yang berlawanan."},{"question":"Apakah maksud “prihatin”?","options":["tidak peduli","suka bermegah","cepat berputus asa","mengambil berat tentang orang lain"],"correct_option_index":3,"explanation":"Prihatin bermaksud peka dan mengambil berat."},{"question":"Apakah kata seerti bagi “tabah”?","options":["gementar","lalai","cekalkan hati","mudah menyerah"],"correct_option_index":2,"explanation":"Tabah bermaksud tetap kuat menghadapi kesukaran."},{"question":"Apakah kata lawan bagi “berani”?","options":["gagah","takut","yakin","tegas"],"correct_option_index":1,"explanation":"Takut ialah keadaan yang bertentangan dengan berani."},{"question":"Apakah maksud “amanah”?","options":["boleh dipercayai","mudah lupa","suka bertengkar","enggan membantu"],"correct_option_index":0,"explanation":"Orang amanah boleh dipercayai melaksanakan tanggungjawab."},{"question":"Apakah kata seerti bagi “indah”?","options":["kusam","hodoh","suram","cantik"],"correct_option_index":3,"explanation":"Indah dan cantik menggambarkan sesuatu yang menarik dipandang."},{"question":"Apakah maksud “tolong-menolong”?","options":["berebut hadiah","bekerja bersendirian","saling membantu","saling menyalahkan"],"correct_option_index":2,"explanation":"Tolong-menolong ialah perbuatan membantu antara satu sama lain."},{"question":"Apakah kata lawan bagi “murah”?","options":["ringan","mahal","rendah","kecil"],"correct_option_index":1,"explanation":"Murah dan mahal merujuk kepada perbezaan harga."},{"question":"Apakah maksud “cermat”?","options":["teliti dan berhati-hati","tergesa-gesa","cuai","sambil lewa"],"correct_option_index":0,"explanation":"Cermat menunjukkan ketelitian dan sikap berhati-hati."},{"question":"Apakah kata seerti bagi “gigih”?","options":["sambil lewa","malas","ragu-ragu","bersungguh-sungguh"],"correct_option_index":3,"explanation":"Gigih bermaksud berusaha dengan kuat dan berterusan."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000004","title":"Bahasa Melayu: Tatabahasa Praktikal","subject":"Bahasa Melayu","grade_level":"Tahun 6","language":"ms","description":"20 soalan kata sendi, imbuhan, ayat dan simpulan bahasa.","questions":[{"question":"Pilih kata sendi nama yang betul: “Ali pergi ___ sekolah.”","options":["daripada","ke","di","dari"],"correct_option_index":1,"explanation":"Kata sendi ke menunjukkan arah atau destinasi."},{"question":"Pilih ayat yang betul.","options":["Mereka sedang membaca buku.","Mereka sedang dibaca buku.","Mereka sedang membaca-bacaan buku.","Mereka sedang pembaca buku."],"correct_option_index":0,"explanation":"Kata kerja membaca sesuai digunakan selepas sedang."},{"question":"Pilih penjodoh bilangan: “Se___ pisang.”","options":["ekor","batang","helai","sikat"],"correct_option_index":3,"explanation":"Pisang yang tersusun dalam satu kumpulan kecil disebut sesikat."},{"question":"Pilih kata sendi nama: “Hadiah itu ___ ibu.”","options":["di","kepada","daripada","ke"],"correct_option_index":2,"explanation":"Daripada boleh menunjukkan sumber atau pemberi."},{"question":"Apakah jenis kata bagi “cantik”?","options":["kata hubung","kata adjektif","kata kerja","kata sendi"],"correct_option_index":1,"explanation":"Cantik menerangkan sifat sesuatu."},{"question":"Pilih imbuhan yang betul: “Dia sedang ___ surat.”","options":["menulis","tertulis","penulis","tulisan"],"correct_option_index":0,"explanation":"Menulis ialah kata kerja aktif."},{"question":"Pilih kata hubung yang sesuai: “Saya belajar ___ adik bermain.”","options":["kerana","supaya","sehingga","manakala"],"correct_option_index":3,"explanation":"Manakala menghubungkan dua keadaan berbeza yang berlaku serentak."},{"question":"Pilih perkataan yang betul: “Buku ini ___ meja.”","options":["dari atas","kepada atas","di atas","ke atas"],"correct_option_index":2,"explanation":"Di atas menunjukkan kedudukan."},{"question":"Apakah maksud simpulan bahasa “ringan tulang”?","options":["kuat makan","rajin membantu","sangat kurus","cepat berlari"],"correct_option_index":1,"explanation":"Ringan tulang menggambarkan orang yang suka bekerja atau membantu."},{"question":"Apakah maksud “buah tangan”?","options":["hadiah yang dibawa ketika melawat","buah yang baru dipetik","hasil peperiksaan","peralatan sukan"],"correct_option_index":0,"explanation":"Buah tangan ialah hadiah yang dibawa untuk seseorang."},{"question":"Pilih kata bilangan yang sesuai: “___ murid hadir.”","options":["Hanya sekali","Kelmarin","Sangat","Semua"],"correct_option_index":3,"explanation":"Semua merujuk kepada keseluruhan murid."},{"question":"Pilih kata tanya: “___ nama guru kamu?”","options":["Di manakah","Mengapakah","Siapakah","Bilakah"],"correct_option_index":2,"explanation":"Siapakah digunakan untuk bertanya tentang orang."},{"question":"Pilih kata tanya: “___ kamu tiba?”","options":["Berapa","Bilakah","Siapakah","Apakah"],"correct_option_index":1,"explanation":"Bilakah digunakan untuk bertanya masa."},{"question":"Pilih ayat perintah.","options":["Sila tutup pintu itu.","Pintu itu berwarna biru.","Adakah pintu itu terbuka?","Alangkah cantiknya pintu itu!"],"correct_option_index":0,"explanation":"Sila ialah penanda arahan yang sopan."},{"question":"Pilih kata ganda yang betul.","options":["murid muridan","bermurid-muridkan","kemuridan","murid-murid"],"correct_option_index":3,"explanation":"Murid-murid menunjukkan bilangan ramai."},{"question":"Pilih penjodoh bilangan: “Se___ pensel.”","options":["helai","utas","batang","ekor"],"correct_option_index":2,"explanation":"Pensel lazimnya menggunakan penjodoh bilangan batang."},{"question":"Pilih kata hubung sebab: “Dia tidak hadir ___ demam.”","options":["sementara","kerana","walaupun","tetapi"],"correct_option_index":1,"explanation":"Kerana menyatakan sebab."},{"question":"Pilih kata sendi: “Kami menunggu ___ perhentian bas.”","options":["di","ke","daripada","kepada"],"correct_option_index":0,"explanation":"Di menunjukkan lokasi."},{"question":"Pilih ayat tanya yang betul.","options":["Sila kamu lewat.","Kamu lewat sangat!","Saya lewat hari ini.","Mengapakah kamu lewat?"],"correct_option_index":3,"explanation":"Mengapakah digunakan untuk menanyakan sebab."},{"question":"Apakah maksud “besar hati”?","options":["marah pada orang lain","berjalan dengan cepat","berasa gembira atau bangga","mempunyai organ yang besar"],"correct_option_index":2,"explanation":"Besar hati bermaksud berasa gembira, bangga atau sukacita."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000005","title":"Digital Citizenship & Online Safety","subject":"Internet Safety","grade_level":"Year 6","language":"en","description":"20 scenario-based questions on privacy, passwords, scams and responsible technology use.","questions":[{"question":"A classmate sends a suspicious shortened link. What should you do first?","options":["Check its source before opening","Open it immediately","Forward it to everyone","Enter your password"],"correct_option_index":0,"explanation":"Links from unknown sources should be verified before opening."},{"question":"Which password is hardest to guess?","options":["12345678","Your first name","password123","A long unique passphrase"],"correct_option_index":3,"explanation":"Long, unique passphrases resist common guessing attacks."},{"question":"A website asks for your one-time login code. What is safest?","options":["Send it to a stranger","Put it on social media","Do not share the code with anyone","Post it on a group chat"],"correct_option_index":2,"explanation":"One-time codes are security credentials meant for your own login."},{"question":"What does multi-factor authentication add?","options":["A faster Wi-Fi connection","An extra verification step","A public password list","An automatic virus"],"correct_option_index":1,"explanation":"MFA requires more than one proof of identity."},{"question":"A game account offers free prizes for your password. What should you do?","options":["Refuse and report the request","Share it just once","Try a friend''s password","Disable account alerts"],"correct_option_index":0,"explanation":"Legitimate prize offers do not require revealing your password."},{"question":"Which personal detail should not be posted publicly?","options":["Your favorite colour","A book genre you enjoy","Your favorite subject","Your home address"],"correct_option_index":3,"explanation":"A home address can expose your physical location."},{"question":"What is phishing?","options":["An official school lesson","A computer screen setting","A trick to steal information using fake messages","A type of safe backup"],"correct_option_index":2,"explanation":"Phishing messages impersonate trusted sources to obtain secrets."},{"question":"A message claims “Act in two minutes or lose your account.” What is a warning sign?","options":["An informative subject","Pressure to act urgently","Correct punctuation","A clear sender address"],"correct_option_index":1,"explanation":"Scammers often manufacture urgency to reduce careful checking."},{"question":"Which action protects a shared classroom tablet?","options":["Sign out after using your account","Leave the account open","Save passwords for everyone","Disable the lock screen"],"correct_option_index":0,"explanation":"Signing out limits later access to your account."},{"question":"What is the safest response to online bullying?","options":["Reply with insults","Share the abuse widely","Reveal the bully''s address","Save evidence and tell a trusted adult"],"correct_option_index":3,"explanation":"Reporting and seeking help is safer than escalation or retaliation."},{"question":"Which data practice is safest for a student quiz?","options":["Publish student passwords","Record private messages","Collect only information needed for participation","Require home addresses for everyone"],"correct_option_index":2,"explanation":"Data minimization reduces privacy risk."},{"question":"Why should a school app use HTTPS?","options":["It prevents every website bug","It encrypts data while travelling over the network","It removes all online threats","It makes passwords unnecessary"],"correct_option_index":1,"explanation":"HTTPS protects data in transit, but does not fix every security issue."},{"question":"A browser warns that a certificate is invalid. What should you do?","options":["Avoid entering personal information","Ignore the warning","Enter payment details anyway","Install an unknown extension"],"correct_option_index":0,"explanation":"An invalid certificate can indicate an unsafe connection."},{"question":"Why is updating software important?","options":["Updates always delete all viruses","Old software never works","Updates share your password","Updates often fix security weaknesses"],"correct_option_index":3,"explanation":"Security patches can close known vulnerabilities."},{"question":"Which permission is unnecessary for a basic maths quiz?","options":["Reading your typed answers","Saving your current score","Access to all your contacts","Displaying quiz questions"],"correct_option_index":2,"explanation":"A basic quiz usually does not need access to your contacts."},{"question":"A stranger online asks where you are studying today. What is safest?","options":["Share a classroom photo with location","Do not reveal your live location","Send GPS coordinates","Post your school schedule"],"correct_option_index":1,"explanation":"Live location information can put privacy and safety at risk."},{"question":"What does a privacy setting control?","options":["Who can access certain account information","How fast a CPU runs","Your screen brightness","The length of a school holiday"],"correct_option_index":0,"explanation":"Privacy settings manage visibility and data sharing."},{"question":"A friend has shared a password with you. What is appropriate?","options":["Post it to test security","Use it without permission","Send it to more people","Encourage them to change it and keep it private"],"correct_option_index":3,"explanation":"Credentials should not be reused or distributed."},{"question":"Why should files be backed up?","options":["To increase screen glare","To stop every hardware problem","To recover important work after loss or damage","To make passwords public"],"correct_option_index":2,"explanation":"Backups support recovery when files are lost or damaged."},{"question":"Which rule helps identify an AI-generated claim?","options":["Assume every image is authentic","Check reliable sources before believing it","Accept it because it sounds confident","Share it without reading"],"correct_option_index":1,"explanation":"AI can make mistakes, so important claims need independent verification."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000006","title":"Science: Plants, Energy & Ecosystems","subject":"Science","grade_level":"Year 6","language":"en","description":"20 science questions about living systems, food webs, materials and everyday energy.","questions":[{"question":"Which part of a plant absorbs most water from soil?","options":["Petals","Fruit","Flowers","Roots"],"correct_option_index":3,"explanation":"Roots take up water and dissolved minerals."},{"question":"What gas do plants mainly take in during photosynthesis?","options":["Hydrogen","Helium","Carbon dioxide","Oxygen"],"correct_option_index":2,"explanation":"Photosynthesis uses carbon dioxide and water to make sugars."},{"question":"What do we call an animal that eats only plants?","options":["Decomposer","Herbivore","Carnivore","Omnivore"],"correct_option_index":1,"explanation":"Herbivores feed on plants."},{"question":"Which organism is a producer in a food chain?","options":["Grass","Rabbit","Fox","Frog"],"correct_option_index":0,"explanation":"Grass makes its own food using sunlight."},{"question":"What is evaporation?","options":["Ice turning into water","Rain falling from clouds","Water freezing","Liquid water changing into water vapour"],"correct_option_index":3,"explanation":"During evaporation liquid particles escape into the gas phase."},{"question":"Which process forms water droplets on a cold glass?","options":["Boiling","Sublimation","Condensation","Melting"],"correct_option_index":2,"explanation":"Water vapour cools and condenses into droplets."},{"question":"Which energy source is renewable?","options":["Natural gas","Sunlight","Coal","Crude oil"],"correct_option_index":1,"explanation":"Sunlight is replenished naturally and is renewable."},{"question":"What happens when a torch battery runs out of usable energy?","options":["The light eventually stops shining","The bulb becomes heavier","Gravity disappears","The torch makes more batteries"],"correct_option_index":0,"explanation":"A torch needs an energy source to keep producing light."},{"question":"Which material usually conducts electricity well?","options":["Dry rubber","Plastic","Glass","Copper"],"correct_option_index":3,"explanation":"Copper has mobile electrons that support electrical conduction."},{"question":"Why does a metal spoon feel cooler than a wooden spoon in the same room?","options":["Wood is always hotter than air","Metal creates cold energy","Metal conducts heat away from the hand faster","Metal has no heat"],"correct_option_index":2,"explanation":"The difference is mainly heat transfer, not necessarily temperature."},{"question":"What is a food web?","options":["A list of plant names","A network of connected food chains","Only one animal''s meal","A drawing of spider silk"],"correct_option_index":1,"explanation":"Food webs represent multiple feeding relationships."},{"question":"Why are decomposers important?","options":["They recycle nutrients from dead material","They create all sunlight","They stop all rainfall","They eat only rocks"],"correct_option_index":0,"explanation":"Decomposers break down remains and return nutrients to ecosystems."},{"question":"Which organ helps humans exchange oxygen and carbon dioxide?","options":["Stomach","Liver","Kidneys","Lungs"],"correct_option_index":3,"explanation":"Gas exchange occurs in the lungs."},{"question":"What is a simple example of a chemical change?","options":["Paper folding","Glass breaking","Iron rusting","Ice melting"],"correct_option_index":2,"explanation":"Rusting forms new substances."},{"question":"Which force pulls a dropped ball toward Earth?","options":["Air resistance alone","Gravity","Magnetism alone","Friction alone"],"correct_option_index":1,"explanation":"Earth''s gravity attracts masses toward its centre."},{"question":"When a shadow becomes shorter at midday, what mainly changed?","options":["The Sun''s apparent position in the sky","The object''s mass","The speed of sound","The air''s oxygen level"],"correct_option_index":0,"explanation":"The sunlight angle changes the length of a shadow."},{"question":"Which change could harm a pond ecosystem?","options":["Removing litter safely","Protecting native plants","Reducing pollution","Dumping waste into the water"],"correct_option_index":3,"explanation":"Waste pollution can damage organisms and water quality."},{"question":"Which structure protects a plant cell and helps it keep shape?","options":["Skeleton","Feather","Cell wall","Wing"],"correct_option_index":2,"explanation":"Plant cell walls provide support outside the cell membrane."},{"question":"Which tool measures air temperature?","options":["Stopwatch","Thermometer","Ruler","Compass"],"correct_option_index":1,"explanation":"A thermometer measures temperature."},{"question":"Why do scientists repeat experiments?","options":["To check whether results are reliable","To guarantee the desired answer","To change all variables randomly","To avoid measuring anything"],"correct_option_index":0,"explanation":"Repeating trials helps identify variability and reliability."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000007","title":"English: Grammar in Real Life","subject":"English","grade_level":"Year 6","language":"en","description":"20 practical English punctuation, vocabulary, sentence and comprehension questions.","questions":[{"question":"Choose the correct sentence.","options":["She going school every day.","She gone to school every day.","She goes to school every day.","She go to school every day."],"correct_option_index":2,"explanation":"The third-person singular present tense uses goes."},{"question":"Choose the correct past-tense sentence.","options":["They visits the museum yesterday.","They visited the museum yesterday.","They visit the museum yesterday.","They visiting the museum yesterday."],"correct_option_index":1,"explanation":"Visited is the regular past tense of visit."},{"question":"Which word is an adverb in “He spoke quietly”?","options":["quietly","He","spoke","none"],"correct_option_index":0,"explanation":"Quietly describes how he spoke."},{"question":"Choose the correct article: “I saw ___ elephant.”","options":["a","thee","no article","an"],"correct_option_index":3,"explanation":"Elephant begins with a vowel sound, so an is appropriate."},{"question":"Choose the correct plural of “child.”","options":["childes","childrens","children","childs"],"correct_option_index":2,"explanation":"Children is an irregular plural."},{"question":"Choose the correct possessive form meaning the bag belongs to one girl.","options":["the girl bag","the girl''s bag","the girls bag","the girls'' bag"],"correct_option_index":1,"explanation":"The apostrophe before s marks one girl''s possession."},{"question":"Which sentence is a question?","options":["Where did you put the keys?","Close the door.","The keys are here.","What a lovely day!"],"correct_option_index":0,"explanation":"It directly asks for information."},{"question":"Choose the correct conjunction: “I stayed home ___ it was raining.”","options":["unless","although","while","because"],"correct_option_index":3,"explanation":"Because explains the reason for staying home."},{"question":"What is an antonym of “generous”?","options":["giving","helpful","selfish","kind"],"correct_option_index":2,"explanation":"Selfish contrasts with being willing to give."},{"question":"What is a synonym of “enormous”?","options":["short","huge","tiny","narrow"],"correct_option_index":1,"explanation":"Enormous and huge both mean very large."},{"question":"Choose the correct contraction for “do not.”","options":["don''t","doesn''t","didn''t","won''t"],"correct_option_index":0,"explanation":"Don''t is the contraction of do not."},{"question":"Which word is an adjective in “The bright moon shone”?","options":["moon","shone","The","bright"],"correct_option_index":3,"explanation":"Bright describes the moon."},{"question":"Choose the correct preposition: “The book is ___ the table.”","options":["does","quick","on","bying"],"correct_option_index":2,"explanation":"On describes the book''s position on the table."},{"question":"Which punctuation ends an exclamation?","options":[":","!","?",","],"correct_option_index":1,"explanation":"An exclamation mark expresses strong feeling or surprise."},{"question":"Choose the correct conditional: “If it rains, we ___ indoors.”","options":["will stay","stayed yesterday","staying","was stay"],"correct_option_index":0,"explanation":"Will stay describes a possible future result."},{"question":"What is the main purpose of a topic sentence?","options":["To replace every supporting detail","To list page numbers","To end with random facts","To introduce the paragraph''s main idea"],"correct_option_index":3,"explanation":"A topic sentence helps readers understand a paragraph''s focus."},{"question":"Which sentence uses quotation marks correctly?","options":["“Please be quiet, said Mia.","Please be quiet,” said Mia.","“Please be quiet,” said Mia.","Please be quiet, said “Mia.”"],"correct_option_index":2,"explanation":"Quotation marks enclose the exact words spoken."},{"question":"Choose the correct comparative form of “good.”","options":["most good","better","gooder","bestest"],"correct_option_index":1,"explanation":"Better is the irregular comparative form of good."},{"question":"What is a reliable way to support a factual claim in a report?","options":["Use a relevant, trustworthy source","Repeat an unverified rumour","Invent a quotation","Change the data to fit"],"correct_option_index":0,"explanation":"Evidence from trustworthy sources supports factual writing."},{"question":"What is the difference between a fact and an opinion?","options":["An opinion is always false","Facts cannot be verified","Every sentence is a fact","A fact can be checked against evidence"],"correct_option_index":3,"explanation":"A factual statement is testable; an opinion expresses a judgement or preference."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000008","title":"Malaysia & World Geography Explorer","subject":"Geography","grade_level":"Year 6","language":"en","description":"20 geography questions focused on Malaysia, maps, weather and world regions.","questions":[{"question":"What is the capital city of Malaysia?","options":["Kuching","Kuala Lumpur","George Town","Johor Bahru"],"correct_option_index":1,"explanation":"Kuala Lumpur is Malaysia''s national capital; Putrajaya is the federal administrative centre."},{"question":"Which island is Penang Island connected to by the Penang Bridge?","options":["Peninsular Malaysia","Borneo","Langkawi","Tioman"],"correct_option_index":0,"explanation":"The bridge connects Penang Island to the mainland of Peninsular Malaysia."},{"question":"What is the state capital of Penang?","options":["Butterworth","Alor Setar","Ipoh","George Town"],"correct_option_index":3,"explanation":"George Town is the capital of the state of Penang."},{"question":"Which Malaysian state is located on the island of Borneo?","options":["Melaka","Negeri Sembilan","Sabah","Perlis"],"correct_option_index":2,"explanation":"Sabah and Sarawak are Malaysian states on Borneo."},{"question":"Which strait lies between Peninsular Malaysia and Sumatra?","options":["Bass Strait","Strait of Malacca","Bering Strait","Strait of Gibraltar"],"correct_option_index":1,"explanation":"The Strait of Malacca lies between the Malay Peninsula and Sumatra."},{"question":"What do lines of latitude measure?","options":["Distance north or south of the Equator","Elevation above sea level","Distance from the coast","The age of a mountain"],"correct_option_index":0,"explanation":"Latitude is an angular position north or south of the Equator."},{"question":"What do lines of longitude measure?","options":["Distance below ground","The speed of wind","Ocean water depth","Position east or west of the Prime Meridian"],"correct_option_index":3,"explanation":"Longitude describes east-west position."},{"question":"Which direction does a compass needle generally indicate?","options":["Always west","Downward","North","South-east only"],"correct_option_index":2,"explanation":"A compass needle aligns approximately with Earth''s magnetic field."},{"question":"Which map feature explains symbols used on a map?","options":["Title alone","Legend or key","Scale only","Border only"],"correct_option_index":1,"explanation":"The legend gives the meanings of map symbols."},{"question":"Which map feature helps estimate real-world distances?","options":["Scale","Colour alone","Title","Compass needle only"],"correct_option_index":0,"explanation":"A map scale links map distances to ground distances."},{"question":"What type of climate is common in much of Malaysia?","options":["Polar","Tundra","Mediterranean dry-summer","Tropical"],"correct_option_index":3,"explanation":"Malaysia lies near the Equator and generally has a tropical climate."},{"question":"Which ocean borders the western coast of the Americas?","options":["Indian Ocean","Arctic Ocean","Pacific Ocean","Atlantic Ocean"],"correct_option_index":2,"explanation":"The Pacific lies west of North and South America."},{"question":"Which continent contains the Sahara Desert?","options":["Australia","Africa","Europe","South America"],"correct_option_index":1,"explanation":"The Sahara spans much of North Africa."},{"question":"What is an archipelago?","options":["A group of islands","A single mountain","A type of desert","A wide river"],"correct_option_index":0,"explanation":"An archipelago consists of multiple islands."},{"question":"Why do coastal regions often experience sea breezes during the day?","options":["The sea stops Earth''s rotation","Clouds always move south","Mountains create all wind","Land heats faster than the sea"],"correct_option_index":3,"explanation":"Differences in heating create pressure and airflow patterns."},{"question":"What causes day and night on Earth?","options":["Earth''s distance changing each hour","Seasonal rainfall","Earth''s rotation","The Moon covering the Sun daily"],"correct_option_index":2,"explanation":"Earth rotates on its axis, turning places toward and away from the Sun."},{"question":"Which geographic feature is formed where a river deposits sediment near its mouth?","options":["Canyon","Delta","Glacier","Volcano"],"correct_option_index":1,"explanation":"River sediment can build a delta near the river mouth."},{"question":"Which renewable resource is strongly linked to windy coastal sites?","options":["Wind energy","Coal mining","Crude oil extraction","Peat burning"],"correct_option_index":0,"explanation":"Coastal winds can drive wind turbines where suitable."},{"question":"What is the main purpose of contour lines on a map?","options":["Show internet speed","Mark languages spoken","List historical events","Show elevation and terrain shape"],"correct_option_index":3,"explanation":"Contour lines join points of equal elevation."},{"question":"Why are mangroves valuable along tropical coasts?","options":["They create mountain peaks","They eliminate every storm","They help protect shorelines and support habitats","They remove all tides"],"correct_option_index":2,"explanation":"Mangroves can reduce erosion and provide wildlife habitat."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000009","title":"Computing, Coding & AI Thinking","subject":"Computing","grade_level":"Year 7","language":"en","description":"20 original questions about algorithms, coding concepts, data and thoughtful AI use.","questions":[{"question":"What is an algorithm?","options":["A sequence of steps to solve a problem","A computer''s screen colour","A type of battery","A keyboard layout"],"correct_option_index":0,"explanation":"Algorithms describe ordered steps for completing a task."},{"question":"What does a loop do in a program?","options":["Deletes every file","Changes the screen size","Always stops the computer","Repeats instructions"],"correct_option_index":3,"explanation":"A loop executes a block multiple times."},{"question":"What does a variable store?","options":["Only pictures","A physical keyboard","A value that may change","A permanent computer case"],"correct_option_index":2,"explanation":"Variables hold data used by a program."},{"question":"Which symbol is often used for an assignment in many programming languages?","options":["@","=","?","#"],"correct_option_index":1,"explanation":"Many languages use an equals sign to assign a value, though syntax varies."},{"question":"What is a boolean value?","options":["True or false","Only positive numbers","A drawing format","A web address"],"correct_option_index":0,"explanation":"Boolean logic represents two truth values."},{"question":"What does debugging mean?","options":["Deleting a user''s account","Making the keyboard louder","Purchasing software","Finding and fixing program errors"],"correct_option_index":3,"explanation":"Debugging investigates why code behaves incorrectly."},{"question":"Which data type best represents a person''s age in whole years?","options":["Audio file","Colour gradient","Integer","Image"],"correct_option_index":2,"explanation":"An integer represents a whole number."},{"question":"What is a conditional statement?","options":["A special mouse","Code that chooses an action based on a condition","A list of unrelated emojis","A permanent hardware component"],"correct_option_index":1,"explanation":"Conditionals allow different paths based on true or false checks."},{"question":"What is a function in programming?","options":["A reusable block of instructions","A kind of electricity bill","A computer brand","A printed receipt"],"correct_option_index":0,"explanation":"Functions group instructions for reuse."},{"question":"What is the purpose of testing software?","options":["To guarantee zero future problems","To avoid understanding the design","To remove all users","To check expected and unexpected behaviour"],"correct_option_index":3,"explanation":"Tests find regressions and unexpected behaviour before release."},{"question":"What is training data used for in machine learning?","options":["Replacing the operating system","Building a keyboard","Helping a model learn patterns","Powering a monitor"],"correct_option_index":2,"explanation":"Training algorithms learn statistical patterns from examples."},{"question":"Why should an AI answer be checked?","options":["Every AI answer is a legal document","AI can confidently produce incorrect information","AI never makes mistakes","AI responses are always official"],"correct_option_index":1,"explanation":"Model outputs can be inaccurate or fabricated."},{"question":"What is an example of personal data?","options":["A student''s full home address","A generic multiplication table","A fictional planet name","A random colour palette"],"correct_option_index":0,"explanation":"A home address can identify or locate someone."},{"question":"What does encryption help protect?","options":["The weight of a laptop","Screen brightness","The length of a lesson","Information from unauthorized reading"],"correct_option_index":3,"explanation":"Encryption makes data unreadable without the appropriate key."},{"question":"Which approach makes a program easier to maintain?","options":["Remove all tests","Repeat identical code everywhere","Use clear names and small functions","Keep every variable named x"],"correct_option_index":2,"explanation":"Readable modules make software easier to understand and revise."},{"question":"What is a database?","options":["A plastic computer case","A structured system for storing and retrieving data","A type of USB cable","A screen resolution"],"correct_option_index":1,"explanation":"Databases organise and query stored information."},{"question":"What is an API?","options":["An interface through which software components communicate","A replacement for every password","A computer monitor size","A school timetable"],"correct_option_index":0,"explanation":"An API defines ways programs request and exchange information."},{"question":"Why is input validation important?","options":["It makes all inputs trusted automatically","It turns photos into text","It replaces backups","It checks whether supplied values meet expected rules"],"correct_option_index":3,"explanation":"Validation rejects malformed or unacceptable data."},{"question":"What is rate limiting intended to do?","options":["Generate every question automatically","Disable all students","Restrict excessive requests to a service","Make every password shorter"],"correct_option_index":2,"explanation":"Rate limiting reduces overload and some forms of abuse."},{"question":"Which is a good way to build safer classroom software?","options":["Disable error handling","Test permissions using accounts with different roles","Trust any button click as authorization","Store secret keys in HTML"],"correct_option_index":1,"explanation":"Role-separated testing checks that unauthorized users cannot gain access."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000010","title":"Real-World Maths: Data & Decisions","subject":"Mathematics","grade_level":"Year 6","language":"en","description":"20 reasoning-focused word problems about money, charts, measurement and percentage.","questions":[{"question":"A notebook costs RM8. You buy three. What is the total cost?","options":["RM11","RM16","RM32","RM24"],"correct_option_index":3,"explanation":"Three notebooks cost 3 × RM8 = RM24."},{"question":"A bus has 42 passengers. 15 get off. How many remain?","options":["25","37","27","57"],"correct_option_index":2,"explanation":"42 − 15 = 27 passengers."},{"question":"A class of 30 students has 18 girls. What fraction of the class is girls in simplest form?","options":["5/3","3/5","18/5","2/5"],"correct_option_index":1,"explanation":"18/30 simplifies to 3/5."},{"question":"A shop reduces RM50 by 10%. What is the new price?","options":["RM45","RM40","RM55","RM49"],"correct_option_index":0,"explanation":"10% of RM50 is RM5; RM50 − RM5 = RM45."},{"question":"A rectangle is 8 cm long and 5 cm wide. What is its area?","options":["26 cm²","13 cm²","80 cm²","40 cm²"],"correct_option_index":3,"explanation":"Area equals length × width = 8 × 5 = 40 cm²."},{"question":"A 2-litre bottle is shared equally into four cups. How much is in each cup?","options":["750 mL","200 mL","500 mL","250 mL"],"correct_option_index":2,"explanation":"2 L = 2000 mL; 2000 ÷ 4 = 500 mL."},{"question":"Six test scores are 5, 6, 7, 8, 9, 10. What is their mean?","options":["9","7.5","7","8"],"correct_option_index":1,"explanation":"The sum is 45; the mean is 45 ÷ 6 = 7.5."},{"question":"A cyclist rides 12 km in one hour at a steady speed. How far in 3 hours?","options":["36 km","24 km","15 km","48 km"],"correct_option_index":0,"explanation":"Distance is 12 × 3 = 36 km."},{"question":"What is 0.75 as a fraction in simplest form?","options":["7/5","1/4","4/3","3/4"],"correct_option_index":3,"explanation":"0.75 equals 75/100, which simplifies to 3/4."},{"question":"A bag contains 4 red and 6 blue marbles. What is the probability of picking red?","options":["3/5","1/4","2/5","4/6"],"correct_option_index":2,"explanation":"4 out of 10 marbles are red, so 4/10 = 2/5."},{"question":"What is the perimeter of a square with side 7 cm?","options":["21 cm","28 cm","49 cm","14 cm"],"correct_option_index":1,"explanation":"Four sides of 7 cm give 4 × 7 = 28 cm."},{"question":"A recipe uses 200 g of flour for 4 muffins. How much flour for 10 muffins at the same rate?","options":["500 g","400 g","600 g","800 g"],"correct_option_index":0,"explanation":"Each muffin needs 50 g; 10 need 500 g."},{"question":"What is the next number in 4, 9, 14, 19, ...?","options":["23","25","29","24"],"correct_option_index":3,"explanation":"Each term increases by 5."},{"question":"A train leaves at 14:20 and arrives at 15:05. How long is the journey?","options":["55 minutes","75 minutes","45 minutes","35 minutes"],"correct_option_index":2,"explanation":"From 14:20 to 15:00 is 40 min, plus 5 min."},{"question":"If 25% of a class is absent and the class has 32 students, how many are absent?","options":["16","8","6","12"],"correct_option_index":1,"explanation":"25% is one quarter; 32 ÷ 4 = 8."},{"question":"A box holds 12 pencils. How many boxes are needed for 70 pencils?","options":["6","5","7","8"],"correct_option_index":0,"explanation":"Five boxes hold only 60; six hold 72."},{"question":"What is 3/8 + 2/8?","options":["5/16","1/8","6/8","5/8"],"correct_option_index":3,"explanation":"Add numerators when denominators match: 3/8 + 2/8 = 5/8."},{"question":"A tank has 18 L, and 2.5 L is used. How much remains?","options":["14.5 L","20.5 L","15.5 L","16.5 L"],"correct_option_index":2,"explanation":"18 − 2.5 = 15.5 L."},{"question":"A map uses 1 cm to represent 5 km. How far is 4 cm on the map?","options":["25 km","20 km","9 km","15 km"],"correct_option_index":1,"explanation":"4 × 5 km = 20 km."},{"question":"The prices RM7, RM9, RM11, RM13, RM15 are recorded. What is their median?","options":["RM11","RM9","RM13","RM10"],"correct_option_index":0,"explanation":"The middle value of the five sorted prices is RM11."}]}]'::jsonb AS packs)
INSERT INTO quiz_sets (id,title,subject,grade_level,language,description,status)
SELECT (p.value->>'id')::uuid,p.value->>'title',p.value->>'subject',p.value->>'grade_level',
 p.value->>'language',p.value->>'description','published'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.packs) AS p(value)
ON CONFLICT (id) DO NOTHING;
WITH payload AS (SELECT '[{"id":"c8202611-05a0-4a9b-9f00-000000000001","title":"华文成语与表达大师","subject":"中文","grade_level":"Year 6","language":"zh","description":"20 道原创华文成语、修辞及表达题，适合小学高年级复习。","questions":[{"question":"“画蛇添足”最接近哪种意思？","options":["做多余的事反而坏事","认真完成工作","及时帮助别人","认真计划未来"],"correct_option_index":0,"explanation":"画好蛇后再添脚，反而破坏原有成果。"},{"question":"“守株待兔”提醒我们什么？","options":["要多种树","兔子跑得快","耐心总能成功","不能只凭侥幸等待收获"],"correct_option_index":3,"explanation":"寓言强调不主动努力而只等好运并不可取。"},{"question":"“井底之蛙”形容怎样的人？","options":["喜欢读书的人","乐于旅行的人","见识狭窄的人","善于游泳的人"],"correct_option_index":2,"explanation":"井底的青蛙看到的天空很小，表示眼界有限。"},{"question":"“雪中送炭”强调什么？","options":["事后表扬别人","在困难时给予及时帮助","在冬天卖木炭","雪地里玩耍"],"correct_option_index":1,"explanation":"最有价值的帮助往往发生在对方急需时。"},{"question":"“亡羊补牢”表达什么道理？","options":["发现错误后及时改正仍有意义","丢羊后不能补救","养羊必须建高墙","任何问题都要放弃"],"correct_option_index":0,"explanation":"寓言告诉我们发现漏洞后仍应及时补救。"},{"question":"“自相矛盾”指什么？","options":["两个意见都正确","做事特别迅速","表达十分清楚","说法前后互相冲突"],"correct_option_index":3,"explanation":"互相矛盾的主张不能同时成立。"},{"question":"“掩耳盗铃”比喻什么？","options":["沉着冷静","互相合作","自欺欺人","勤奋学习"],"correct_option_index":2,"explanation":"捂住耳朵不代表别人听不到铃声。"},{"question":"“刻舟求剑”讽刺哪种做法？","options":["保护重要物品","情况变了却仍用旧办法","计划周全","记录航行路线"],"correct_option_index":1,"explanation":"船在前进，落剑的位置不会跟着船上的记号走。"},{"question":"“一举两得”是什么意思？","options":["一次行动获得两种好处","只做一件事","两人一起行动","先失败再成功"],"correct_option_index":0,"explanation":"一个行动同时取得两个积极结果。"},{"question":"“心不在焉”的意思是？","options":["心情愉快","身体强壮","态度友善","注意力不集中"],"correct_option_index":3,"explanation":"心思没有放在正在做的事情上。"},{"question":"“废寝忘食”形容什么？","options":["睡眠充足","生活很规律","专心投入而忘记休息吃饭","讨厌所有食物"],"correct_option_index":2,"explanation":"通常用来形容对某件事投入程度很高。"},{"question":"“百折不挠”体现哪种品质？","options":["从不尝试新事物","遇到挫折仍坚持","随意更换目标","遇难马上逃避"],"correct_option_index":1,"explanation":"“不挠”表示遭遇困难也不轻易屈服。"},{"question":"“滥竽充数”形容什么？","options":["没有本领却混在行家中","乐于学习音乐","团队演奏出色","谦虚请教别人"],"correct_option_index":0,"explanation":"故事中的人不会吹竽，却假装加入乐队。"},{"question":"“胸有成竹”表示什么？","options":["胸前真的有竹子","喜欢画动物","做事全凭运气","做事前已有成熟计划"],"correct_option_index":3,"explanation":"原指画竹前心中已有竹子的形象。"},{"question":"“举一反三”指什么能力？","options":["同时做四件事","改变原来的答案","由一个例子推知相似情形","反复记一个答案"],"correct_option_index":2,"explanation":"理解规律后能迁移运用到类似问题。"},{"question":"“半途而废”的意思是？","options":["一边走路一边学习","事情进行到一半就放弃","提前完成工作","顺利到达终点"],"correct_option_index":1,"explanation":"强调未完成目标就中途停止。"},{"question":"“聚精会神”形容什么？","options":["注意力非常集中","精神疲倦","四处张望","感到害怕"],"correct_option_index":0,"explanation":"“聚”与“会”都加强专注的意思。"},{"question":"“耳濡目染”强调哪种影响？","options":["只靠听力学习","视力得到改善","一次听课就精通","长期接触而受到潜移默化的影响"],"correct_option_index":3,"explanation":"经常听到、看到某事会逐渐受其影响。"},{"question":"“循序渐进”的学习方法是？","options":["每天更换全部教材","只背答案不理解","按照次序逐步提高","跳过基础直接挑战最难题"],"correct_option_index":2,"explanation":"循序渐进强调从基础到复杂、逐步学习。"},{"question":"“同舟共济”适合描述什么场景？","options":["不愿分享信息","大家合作面对困难","每人独自解决所有问题","在船上争吵"],"correct_option_index":1,"explanation":"同乘一船渡河，比喻齐心协力。"}]},{"id":"c8202611-05a0-4a9b-9f00-000000000002","title":"华文语文与阅读思考","subject":"中文","grade_level":"Year 6","language":"zh","description":"20 道标点、句型、词义及阅读理解基础题。","questions":[{"question":"“天空像一块蓝色的画布。”用了什么修辞手法？","options":["反问","设问","排比","比喻"],"correct_option_index":3,"explanation":"“像”把天空比作蓝色画布，是比喻。"},{"question":"“风轻轻地抚摸着树叶。”用了什么修辞手法？","options":["反问","引用","拟人","夸张"],"correct_option_index":2,"explanation":"让风做出人的动作“抚摸”，属于拟人。"},{"question":"哪个句子使用了疑问句？","options":["今天下雨了。","你今天带雨伞了吗？","请带雨伞。","天气真好！"],"correct_option_index":1,"explanation":"疑问句用来提出问题，常以问号结尾。"},{"question":"哪个词语与“勤奋”意思最接近？","options":["努力","懒散","犹豫","粗心"],"correct_option_index":0,"explanation":"勤奋强调认真努力地学习或工作。"},{"question":"“宽阔”的反义词是什么？","options":["辽阔","广大","平坦","狭窄"],"correct_option_index":3,"explanation":"宽阔与狭窄描述空间大小的相反特征。"},{"question":"“因为下雨，所以比赛延期了。”表示什么关系？","options":["假设关系","转折关系","因果关系","并列关系"],"correct_option_index":2,"explanation":"“因为……所以……”连接原因与结果。"},{"question":"“虽然很累，但她仍坚持练习。”表达什么关系？","options":["选择关系","转折关系","因果关系","递进关系"],"correct_option_index":1,"explanation":"“虽然……但……”前后语义有转折。"},{"question":"哪个标点符号用来表示直接问句结束？","options":["问号（？）","句号（。）","逗号（，）","顿号（、）"],"correct_option_index":0,"explanation":"完整的直接疑问句通常用问号。"},{"question":"下列哪组词语是近义词？","options":["高兴—难过","宽阔—狭窄","开始—结束","迅速—快速"],"correct_option_index":3,"explanation":"迅速和快速都表示速度快。"},{"question":"下列哪组词语是反义词？","options":["美丽—漂亮","勇敢—英勇","明亮—昏暗","安静—宁静"],"correct_option_index":2,"explanation":"明亮与昏暗表示光线的相反状态。"},{"question":"“书是知识的钥匙。”中的“钥匙”是什么用法？","options":["拟声词","比喻性的说法","真实开门工具","量词"],"correct_option_index":1,"explanation":"这里把书比作打开知识大门的工具。"},{"question":"“他小心翼翼地放下玻璃杯。”哪个词形容动作态度？","options":["小心翼翼","玻璃杯","放下","他"],"correct_option_index":0,"explanation":"“小心翼翼”描述动作非常谨慎。"},{"question":"写观察日记时最重要的是什么？","options":["编造有趣的结果","只写标题","省略时间和地点","如实记录观察到的现象"],"correct_option_index":3,"explanation":"观察日记应以真实观察为基础。"},{"question":"阅读说明文时，想快速找日期应先做什么？","options":["只读最后一句","忽略所有数字","寻找与日期有关的关键词","逐字背诵全文"],"correct_option_index":2,"explanation":"扫读并抓关键词可以更快定位信息。"},{"question":"“如果明天晴天，我们就去郊游。”是什么关系？","options":["转折关系","条件关系","因果关系","并列关系"],"correct_option_index":1,"explanation":"“如果……就……”说明满足条件才会发生的事情。"},{"question":"下列哪个句子更适合作为正式邀请？","options":["诚邀您参加本周五的交流活动。","快点过来啦！","你必须出现哦！","来嘛，不来不行！"],"correct_option_index":0,"explanation":"正式邀请应礼貌、清晰并说明活动。"},{"question":"写故事时“人物、时间、地点”主要帮助读者了解什么？","options":["答案选项","拼音声调","广告价格","故事背景"],"correct_option_index":3,"explanation":"这三项交代故事发生的基本背景。"},{"question":"“他把一杯水递给口渴的同学。”可以推断他怎么样？","options":["只关心自己","不喜欢水","乐于帮助别人","不愿与人合作"],"correct_option_index":2,"explanation":"主动给口渴的同学水体现关心。"},{"question":"哪一个是正确的量词搭配？","options":["一把天空","一条河","一只书","一本马"],"correct_option_index":1,"explanation":"“河”常用量词“条”。"},{"question":"要判断一篇文章的中心思想，最适合怎么做？","options":["归纳全文反复强调的主要意思","只看第一个生字","计算标点总数","只读标题的最后一个字"],"correct_option_index":0,"explanation":"中心思想需要结合全文内容综合判断。"}]},{"id":"c8202611-05a0-4a9b-9f00-000000000003","title":"Bahasa Melayu: Perbendaharaan Kata","subject":"Bahasa Melayu","grade_level":"Tahun 6","language":"ms","description":"20 soalan kosa kata dan makna perkataan dengan penerangan ringkas.","questions":[{"question":"Apakah kata seerti bagi “gembira”?","options":["marah","penat","riang","sedih"],"correct_option_index":2,"explanation":"Gembira dan riang membawa maksud perasaan suka."},{"question":"Apakah kata lawan bagi “tinggi”?","options":["kuat","rendah","panjang","besar"],"correct_option_index":1,"explanation":"Tinggi dan rendah menunjukkan ukuran ketinggian yang bertentangan."},{"question":"Apakah maksud “rajin”?","options":["tekun melakukan kerja","suka bertangguh","mudah lupa","tidak mengambil peduli"],"correct_option_index":0,"explanation":"Rajin bermaksud bersungguh-sungguh menjalankan tugas."},{"question":"Apakah kata seerti bagi “cepat”?","options":["lambat","senyap","berat","pantas"],"correct_option_index":3,"explanation":"Cepat dan pantas merujuk kepada kelajuan tinggi."},{"question":"Apakah kata lawan bagi “bersih”?","options":["cantik","wangi","kotor","kemas"],"correct_option_index":2,"explanation":"Bersih bertentangan dengan kotor."},{"question":"Apakah maksud “berjimat”?","options":["berbelanja tanpa had","menggunakan wang dengan cermat","membeli semua barang","membuang makanan"],"correct_option_index":1,"explanation":"Berjimat bermaksud tidak membazir sumber atau wang."},{"question":"Apakah kata seerti bagi “bijak”?","options":["pandai","cuai","malas","lemah"],"correct_option_index":0,"explanation":"Bijak dan pandai menggambarkan keupayaan berfikir dengan baik."},{"question":"Apakah kata lawan bagi “gelap”?","options":["suram","malam","kelam","terang"],"correct_option_index":3,"explanation":"Gelap dan terang bertentangan dari segi cahaya."},{"question":"Apakah maksud “berhemah”?","options":["bertindak melulu","suka membazir","berkelakuan sopan","bercakap kasar"],"correct_option_index":2,"explanation":"Berhemah menunjukkan tingkah laku yang tertib dan sopan."},{"question":"Apakah kata seerti bagi “damai”?","options":["marah","aman","bising","cemas"],"correct_option_index":1,"explanation":"Damai dan aman merujuk kepada keadaan tenteram."},{"question":"Apakah kata lawan bagi “sempit”?","options":["luas","kecil","pendek","nipis"],"correct_option_index":0,"explanation":"Sempit dan luas menggambarkan keluasan yang berlawanan."},{"question":"Apakah maksud “prihatin”?","options":["tidak peduli","suka bermegah","cepat berputus asa","mengambil berat tentang orang lain"],"correct_option_index":3,"explanation":"Prihatin bermaksud peka dan mengambil berat."},{"question":"Apakah kata seerti bagi “tabah”?","options":["gementar","lalai","cekalkan hati","mudah menyerah"],"correct_option_index":2,"explanation":"Tabah bermaksud tetap kuat menghadapi kesukaran."},{"question":"Apakah kata lawan bagi “berani”?","options":["gagah","takut","yakin","tegas"],"correct_option_index":1,"explanation":"Takut ialah keadaan yang bertentangan dengan berani."},{"question":"Apakah maksud “amanah”?","options":["boleh dipercayai","mudah lupa","suka bertengkar","enggan membantu"],"correct_option_index":0,"explanation":"Orang amanah boleh dipercayai melaksanakan tanggungjawab."},{"question":"Apakah kata seerti bagi “indah”?","options":["kusam","hodoh","suram","cantik"],"correct_option_index":3,"explanation":"Indah dan cantik menggambarkan sesuatu yang menarik dipandang."},{"question":"Apakah maksud “tolong-menolong”?","options":["berebut hadiah","bekerja bersendirian","saling membantu","saling menyalahkan"],"correct_option_index":2,"explanation":"Tolong-menolong ialah perbuatan membantu antara satu sama lain."},{"question":"Apakah kata lawan bagi “murah”?","options":["ringan","mahal","rendah","kecil"],"correct_option_index":1,"explanation":"Murah dan mahal merujuk kepada perbezaan harga."},{"question":"Apakah maksud “cermat”?","options":["teliti dan berhati-hati","tergesa-gesa","cuai","sambil lewa"],"correct_option_index":0,"explanation":"Cermat menunjukkan ketelitian dan sikap berhati-hati."},{"question":"Apakah kata seerti bagi “gigih”?","options":["sambil lewa","malas","ragu-ragu","bersungguh-sungguh"],"correct_option_index":3,"explanation":"Gigih bermaksud berusaha dengan kuat dan berterusan."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000004","title":"Bahasa Melayu: Tatabahasa Praktikal","subject":"Bahasa Melayu","grade_level":"Tahun 6","language":"ms","description":"20 soalan kata sendi, imbuhan, ayat dan simpulan bahasa.","questions":[{"question":"Pilih kata sendi nama yang betul: “Ali pergi ___ sekolah.”","options":["daripada","ke","di","dari"],"correct_option_index":1,"explanation":"Kata sendi ke menunjukkan arah atau destinasi."},{"question":"Pilih ayat yang betul.","options":["Mereka sedang membaca buku.","Mereka sedang dibaca buku.","Mereka sedang membaca-bacaan buku.","Mereka sedang pembaca buku."],"correct_option_index":0,"explanation":"Kata kerja membaca sesuai digunakan selepas sedang."},{"question":"Pilih penjodoh bilangan: “Se___ pisang.”","options":["ekor","batang","helai","sikat"],"correct_option_index":3,"explanation":"Pisang yang tersusun dalam satu kumpulan kecil disebut sesikat."},{"question":"Pilih kata sendi nama: “Hadiah itu ___ ibu.”","options":["di","kepada","daripada","ke"],"correct_option_index":2,"explanation":"Daripada boleh menunjukkan sumber atau pemberi."},{"question":"Apakah jenis kata bagi “cantik”?","options":["kata hubung","kata adjektif","kata kerja","kata sendi"],"correct_option_index":1,"explanation":"Cantik menerangkan sifat sesuatu."},{"question":"Pilih imbuhan yang betul: “Dia sedang ___ surat.”","options":["menulis","tertulis","penulis","tulisan"],"correct_option_index":0,"explanation":"Menulis ialah kata kerja aktif."},{"question":"Pilih kata hubung yang sesuai: “Saya belajar ___ adik bermain.”","options":["kerana","supaya","sehingga","manakala"],"correct_option_index":3,"explanation":"Manakala menghubungkan dua keadaan berbeza yang berlaku serentak."},{"question":"Pilih perkataan yang betul: “Buku ini ___ meja.”","options":["dari atas","kepada atas","di atas","ke atas"],"correct_option_index":2,"explanation":"Di atas menunjukkan kedudukan."},{"question":"Apakah maksud simpulan bahasa “ringan tulang”?","options":["kuat makan","rajin membantu","sangat kurus","cepat berlari"],"correct_option_index":1,"explanation":"Ringan tulang menggambarkan orang yang suka bekerja atau membantu."},{"question":"Apakah maksud “buah tangan”?","options":["hadiah yang dibawa ketika melawat","buah yang baru dipetik","hasil peperiksaan","peralatan sukan"],"correct_option_index":0,"explanation":"Buah tangan ialah hadiah yang dibawa untuk seseorang."},{"question":"Pilih kata bilangan yang sesuai: “___ murid hadir.”","options":["Hanya sekali","Kelmarin","Sangat","Semua"],"correct_option_index":3,"explanation":"Semua merujuk kepada keseluruhan murid."},{"question":"Pilih kata tanya: “___ nama guru kamu?”","options":["Di manakah","Mengapakah","Siapakah","Bilakah"],"correct_option_index":2,"explanation":"Siapakah digunakan untuk bertanya tentang orang."},{"question":"Pilih kata tanya: “___ kamu tiba?”","options":["Berapa","Bilakah","Siapakah","Apakah"],"correct_option_index":1,"explanation":"Bilakah digunakan untuk bertanya masa."},{"question":"Pilih ayat perintah.","options":["Sila tutup pintu itu.","Pintu itu berwarna biru.","Adakah pintu itu terbuka?","Alangkah cantiknya pintu itu!"],"correct_option_index":0,"explanation":"Sila ialah penanda arahan yang sopan."},{"question":"Pilih kata ganda yang betul.","options":["murid muridan","bermurid-muridkan","kemuridan","murid-murid"],"correct_option_index":3,"explanation":"Murid-murid menunjukkan bilangan ramai."},{"question":"Pilih penjodoh bilangan: “Se___ pensel.”","options":["helai","utas","batang","ekor"],"correct_option_index":2,"explanation":"Pensel lazimnya menggunakan penjodoh bilangan batang."},{"question":"Pilih kata hubung sebab: “Dia tidak hadir ___ demam.”","options":["sementara","kerana","walaupun","tetapi"],"correct_option_index":1,"explanation":"Kerana menyatakan sebab."},{"question":"Pilih kata sendi: “Kami menunggu ___ perhentian bas.”","options":["di","ke","daripada","kepada"],"correct_option_index":0,"explanation":"Di menunjukkan lokasi."},{"question":"Pilih ayat tanya yang betul.","options":["Sila kamu lewat.","Kamu lewat sangat!","Saya lewat hari ini.","Mengapakah kamu lewat?"],"correct_option_index":3,"explanation":"Mengapakah digunakan untuk menanyakan sebab."},{"question":"Apakah maksud “besar hati”?","options":["marah pada orang lain","berjalan dengan cepat","berasa gembira atau bangga","mempunyai organ yang besar"],"correct_option_index":2,"explanation":"Besar hati bermaksud berasa gembira, bangga atau sukacita."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000005","title":"Digital Citizenship & Online Safety","subject":"Internet Safety","grade_level":"Year 6","language":"en","description":"20 scenario-based questions on privacy, passwords, scams and responsible technology use.","questions":[{"question":"A classmate sends a suspicious shortened link. What should you do first?","options":["Check its source before opening","Open it immediately","Forward it to everyone","Enter your password"],"correct_option_index":0,"explanation":"Links from unknown sources should be verified before opening."},{"question":"Which password is hardest to guess?","options":["12345678","Your first name","password123","A long unique passphrase"],"correct_option_index":3,"explanation":"Long, unique passphrases resist common guessing attacks."},{"question":"A website asks for your one-time login code. What is safest?","options":["Send it to a stranger","Put it on social media","Do not share the code with anyone","Post it on a group chat"],"correct_option_index":2,"explanation":"One-time codes are security credentials meant for your own login."},{"question":"What does multi-factor authentication add?","options":["A faster Wi-Fi connection","An extra verification step","A public password list","An automatic virus"],"correct_option_index":1,"explanation":"MFA requires more than one proof of identity."},{"question":"A game account offers free prizes for your password. What should you do?","options":["Refuse and report the request","Share it just once","Try a friend''s password","Disable account alerts"],"correct_option_index":0,"explanation":"Legitimate prize offers do not require revealing your password."},{"question":"Which personal detail should not be posted publicly?","options":["Your favorite colour","A book genre you enjoy","Your favorite subject","Your home address"],"correct_option_index":3,"explanation":"A home address can expose your physical location."},{"question":"What is phishing?","options":["An official school lesson","A computer screen setting","A trick to steal information using fake messages","A type of safe backup"],"correct_option_index":2,"explanation":"Phishing messages impersonate trusted sources to obtain secrets."},{"question":"A message claims “Act in two minutes or lose your account.” What is a warning sign?","options":["An informative subject","Pressure to act urgently","Correct punctuation","A clear sender address"],"correct_option_index":1,"explanation":"Scammers often manufacture urgency to reduce careful checking."},{"question":"Which action protects a shared classroom tablet?","options":["Sign out after using your account","Leave the account open","Save passwords for everyone","Disable the lock screen"],"correct_option_index":0,"explanation":"Signing out limits later access to your account."},{"question":"What is the safest response to online bullying?","options":["Reply with insults","Share the abuse widely","Reveal the bully''s address","Save evidence and tell a trusted adult"],"correct_option_index":3,"explanation":"Reporting and seeking help is safer than escalation or retaliation."},{"question":"Which data practice is safest for a student quiz?","options":["Publish student passwords","Record private messages","Collect only information needed for participation","Require home addresses for everyone"],"correct_option_index":2,"explanation":"Data minimization reduces privacy risk."},{"question":"Why should a school app use HTTPS?","options":["It prevents every website bug","It encrypts data while travelling over the network","It removes all online threats","It makes passwords unnecessary"],"correct_option_index":1,"explanation":"HTTPS protects data in transit, but does not fix every security issue."},{"question":"A browser warns that a certificate is invalid. What should you do?","options":["Avoid entering personal information","Ignore the warning","Enter payment details anyway","Install an unknown extension"],"correct_option_index":0,"explanation":"An invalid certificate can indicate an unsafe connection."},{"question":"Why is updating software important?","options":["Updates always delete all viruses","Old software never works","Updates share your password","Updates often fix security weaknesses"],"correct_option_index":3,"explanation":"Security patches can close known vulnerabilities."},{"question":"Which permission is unnecessary for a basic maths quiz?","options":["Reading your typed answers","Saving your current score","Access to all your contacts","Displaying quiz questions"],"correct_option_index":2,"explanation":"A basic quiz usually does not need access to your contacts."},{"question":"A stranger online asks where you are studying today. What is safest?","options":["Share a classroom photo with location","Do not reveal your live location","Send GPS coordinates","Post your school schedule"],"correct_option_index":1,"explanation":"Live location information can put privacy and safety at risk."},{"question":"What does a privacy setting control?","options":["Who can access certain account information","How fast a CPU runs","Your screen brightness","The length of a school holiday"],"correct_option_index":0,"explanation":"Privacy settings manage visibility and data sharing."},{"question":"A friend has shared a password with you. What is appropriate?","options":["Post it to test security","Use it without permission","Send it to more people","Encourage them to change it and keep it private"],"correct_option_index":3,"explanation":"Credentials should not be reused or distributed."},{"question":"Why should files be backed up?","options":["To increase screen glare","To stop every hardware problem","To recover important work after loss or damage","To make passwords public"],"correct_option_index":2,"explanation":"Backups support recovery when files are lost or damaged."},{"question":"Which rule helps identify an AI-generated claim?","options":["Assume every image is authentic","Check reliable sources before believing it","Accept it because it sounds confident","Share it without reading"],"correct_option_index":1,"explanation":"AI can make mistakes, so important claims need independent verification."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000006","title":"Science: Plants, Energy & Ecosystems","subject":"Science","grade_level":"Year 6","language":"en","description":"20 science questions about living systems, food webs, materials and everyday energy.","questions":[{"question":"Which part of a plant absorbs most water from soil?","options":["Petals","Fruit","Flowers","Roots"],"correct_option_index":3,"explanation":"Roots take up water and dissolved minerals."},{"question":"What gas do plants mainly take in during photosynthesis?","options":["Hydrogen","Helium","Carbon dioxide","Oxygen"],"correct_option_index":2,"explanation":"Photosynthesis uses carbon dioxide and water to make sugars."},{"question":"What do we call an animal that eats only plants?","options":["Decomposer","Herbivore","Carnivore","Omnivore"],"correct_option_index":1,"explanation":"Herbivores feed on plants."},{"question":"Which organism is a producer in a food chain?","options":["Grass","Rabbit","Fox","Frog"],"correct_option_index":0,"explanation":"Grass makes its own food using sunlight."},{"question":"What is evaporation?","options":["Ice turning into water","Rain falling from clouds","Water freezing","Liquid water changing into water vapour"],"correct_option_index":3,"explanation":"During evaporation liquid particles escape into the gas phase."},{"question":"Which process forms water droplets on a cold glass?","options":["Boiling","Sublimation","Condensation","Melting"],"correct_option_index":2,"explanation":"Water vapour cools and condenses into droplets."},{"question":"Which energy source is renewable?","options":["Natural gas","Sunlight","Coal","Crude oil"],"correct_option_index":1,"explanation":"Sunlight is replenished naturally and is renewable."},{"question":"What happens when a torch battery runs out of usable energy?","options":["The light eventually stops shining","The bulb becomes heavier","Gravity disappears","The torch makes more batteries"],"correct_option_index":0,"explanation":"A torch needs an energy source to keep producing light."},{"question":"Which material usually conducts electricity well?","options":["Dry rubber","Plastic","Glass","Copper"],"correct_option_index":3,"explanation":"Copper has mobile electrons that support electrical conduction."},{"question":"Why does a metal spoon feel cooler than a wooden spoon in the same room?","options":["Wood is always hotter than air","Metal creates cold energy","Metal conducts heat away from the hand faster","Metal has no heat"],"correct_option_index":2,"explanation":"The difference is mainly heat transfer, not necessarily temperature."},{"question":"What is a food web?","options":["A list of plant names","A network of connected food chains","Only one animal''s meal","A drawing of spider silk"],"correct_option_index":1,"explanation":"Food webs represent multiple feeding relationships."},{"question":"Why are decomposers important?","options":["They recycle nutrients from dead material","They create all sunlight","They stop all rainfall","They eat only rocks"],"correct_option_index":0,"explanation":"Decomposers break down remains and return nutrients to ecosystems."},{"question":"Which organ helps humans exchange oxygen and carbon dioxide?","options":["Stomach","Liver","Kidneys","Lungs"],"correct_option_index":3,"explanation":"Gas exchange occurs in the lungs."},{"question":"What is a simple example of a chemical change?","options":["Paper folding","Glass breaking","Iron rusting","Ice melting"],"correct_option_index":2,"explanation":"Rusting forms new substances."},{"question":"Which force pulls a dropped ball toward Earth?","options":["Air resistance alone","Gravity","Magnetism alone","Friction alone"],"correct_option_index":1,"explanation":"Earth''s gravity attracts masses toward its centre."},{"question":"When a shadow becomes shorter at midday, what mainly changed?","options":["The Sun''s apparent position in the sky","The object''s mass","The speed of sound","The air''s oxygen level"],"correct_option_index":0,"explanation":"The sunlight angle changes the length of a shadow."},{"question":"Which change could harm a pond ecosystem?","options":["Removing litter safely","Protecting native plants","Reducing pollution","Dumping waste into the water"],"correct_option_index":3,"explanation":"Waste pollution can damage organisms and water quality."},{"question":"Which structure protects a plant cell and helps it keep shape?","options":["Skeleton","Feather","Cell wall","Wing"],"correct_option_index":2,"explanation":"Plant cell walls provide support outside the cell membrane."},{"question":"Which tool measures air temperature?","options":["Stopwatch","Thermometer","Ruler","Compass"],"correct_option_index":1,"explanation":"A thermometer measures temperature."},{"question":"Why do scientists repeat experiments?","options":["To check whether results are reliable","To guarantee the desired answer","To change all variables randomly","To avoid measuring anything"],"correct_option_index":0,"explanation":"Repeating trials helps identify variability and reliability."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000007","title":"English: Grammar in Real Life","subject":"English","grade_level":"Year 6","language":"en","description":"20 practical English punctuation, vocabulary, sentence and comprehension questions.","questions":[{"question":"Choose the correct sentence.","options":["She going school every day.","She gone to school every day.","She goes to school every day.","She go to school every day."],"correct_option_index":2,"explanation":"The third-person singular present tense uses goes."},{"question":"Choose the correct past-tense sentence.","options":["They visits the museum yesterday.","They visited the museum yesterday.","They visit the museum yesterday.","They visiting the museum yesterday."],"correct_option_index":1,"explanation":"Visited is the regular past tense of visit."},{"question":"Which word is an adverb in “He spoke quietly”?","options":["quietly","He","spoke","none"],"correct_option_index":0,"explanation":"Quietly describes how he spoke."},{"question":"Choose the correct article: “I saw ___ elephant.”","options":["a","thee","no article","an"],"correct_option_index":3,"explanation":"Elephant begins with a vowel sound, so an is appropriate."},{"question":"Choose the correct plural of “child.”","options":["childes","childrens","children","childs"],"correct_option_index":2,"explanation":"Children is an irregular plural."},{"question":"Choose the correct possessive form meaning the bag belongs to one girl.","options":["the girl bag","the girl''s bag","the girls bag","the girls'' bag"],"correct_option_index":1,"explanation":"The apostrophe before s marks one girl''s possession."},{"question":"Which sentence is a question?","options":["Where did you put the keys?","Close the door.","The keys are here.","What a lovely day!"],"correct_option_index":0,"explanation":"It directly asks for information."},{"question":"Choose the correct conjunction: “I stayed home ___ it was raining.”","options":["unless","although","while","because"],"correct_option_index":3,"explanation":"Because explains the reason for staying home."},{"question":"What is an antonym of “generous”?","options":["giving","helpful","selfish","kind"],"correct_option_index":2,"explanation":"Selfish contrasts with being willing to give."},{"question":"What is a synonym of “enormous”?","options":["short","huge","tiny","narrow"],"correct_option_index":1,"explanation":"Enormous and huge both mean very large."},{"question":"Choose the correct contraction for “do not.”","options":["don''t","doesn''t","didn''t","won''t"],"correct_option_index":0,"explanation":"Don''t is the contraction of do not."},{"question":"Which word is an adjective in “The bright moon shone”?","options":["moon","shone","The","bright"],"correct_option_index":3,"explanation":"Bright describes the moon."},{"question":"Choose the correct preposition: “The book is ___ the table.”","options":["does","quick","on","bying"],"correct_option_index":2,"explanation":"On describes the book''s position on the table."},{"question":"Which punctuation ends an exclamation?","options":[":","!","?",","],"correct_option_index":1,"explanation":"An exclamation mark expresses strong feeling or surprise."},{"question":"Choose the correct conditional: “If it rains, we ___ indoors.”","options":["will stay","stayed yesterday","staying","was stay"],"correct_option_index":0,"explanation":"Will stay describes a possible future result."},{"question":"What is the main purpose of a topic sentence?","options":["To replace every supporting detail","To list page numbers","To end with random facts","To introduce the paragraph''s main idea"],"correct_option_index":3,"explanation":"A topic sentence helps readers understand a paragraph''s focus."},{"question":"Which sentence uses quotation marks correctly?","options":["“Please be quiet, said Mia.","Please be quiet,” said Mia.","“Please be quiet,” said Mia.","Please be quiet, said “Mia.”"],"correct_option_index":2,"explanation":"Quotation marks enclose the exact words spoken."},{"question":"Choose the correct comparative form of “good.”","options":["most good","better","gooder","bestest"],"correct_option_index":1,"explanation":"Better is the irregular comparative form of good."},{"question":"What is a reliable way to support a factual claim in a report?","options":["Use a relevant, trustworthy source","Repeat an unverified rumour","Invent a quotation","Change the data to fit"],"correct_option_index":0,"explanation":"Evidence from trustworthy sources supports factual writing."},{"question":"What is the difference between a fact and an opinion?","options":["An opinion is always false","Facts cannot be verified","Every sentence is a fact","A fact can be checked against evidence"],"correct_option_index":3,"explanation":"A factual statement is testable; an opinion expresses a judgement or preference."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000008","title":"Malaysia & World Geography Explorer","subject":"Geography","grade_level":"Year 6","language":"en","description":"20 geography questions focused on Malaysia, maps, weather and world regions.","questions":[{"question":"What is the capital city of Malaysia?","options":["Kuching","Kuala Lumpur","George Town","Johor Bahru"],"correct_option_index":1,"explanation":"Kuala Lumpur is Malaysia''s national capital; Putrajaya is the federal administrative centre."},{"question":"Which island is Penang Island connected to by the Penang Bridge?","options":["Peninsular Malaysia","Borneo","Langkawi","Tioman"],"correct_option_index":0,"explanation":"The bridge connects Penang Island to the mainland of Peninsular Malaysia."},{"question":"What is the state capital of Penang?","options":["Butterworth","Alor Setar","Ipoh","George Town"],"correct_option_index":3,"explanation":"George Town is the capital of the state of Penang."},{"question":"Which Malaysian state is located on the island of Borneo?","options":["Melaka","Negeri Sembilan","Sabah","Perlis"],"correct_option_index":2,"explanation":"Sabah and Sarawak are Malaysian states on Borneo."},{"question":"Which strait lies between Peninsular Malaysia and Sumatra?","options":["Bass Strait","Strait of Malacca","Bering Strait","Strait of Gibraltar"],"correct_option_index":1,"explanation":"The Strait of Malacca lies between the Malay Peninsula and Sumatra."},{"question":"What do lines of latitude measure?","options":["Distance north or south of the Equator","Elevation above sea level","Distance from the coast","The age of a mountain"],"correct_option_index":0,"explanation":"Latitude is an angular position north or south of the Equator."},{"question":"What do lines of longitude measure?","options":["Distance below ground","The speed of wind","Ocean water depth","Position east or west of the Prime Meridian"],"correct_option_index":3,"explanation":"Longitude describes east-west position."},{"question":"Which direction does a compass needle generally indicate?","options":["Always west","Downward","North","South-east only"],"correct_option_index":2,"explanation":"A compass needle aligns approximately with Earth''s magnetic field."},{"question":"Which map feature explains symbols used on a map?","options":["Title alone","Legend or key","Scale only","Border only"],"correct_option_index":1,"explanation":"The legend gives the meanings of map symbols."},{"question":"Which map feature helps estimate real-world distances?","options":["Scale","Colour alone","Title","Compass needle only"],"correct_option_index":0,"explanation":"A map scale links map distances to ground distances."},{"question":"What type of climate is common in much of Malaysia?","options":["Polar","Tundra","Mediterranean dry-summer","Tropical"],"correct_option_index":3,"explanation":"Malaysia lies near the Equator and generally has a tropical climate."},{"question":"Which ocean borders the western coast of the Americas?","options":["Indian Ocean","Arctic Ocean","Pacific Ocean","Atlantic Ocean"],"correct_option_index":2,"explanation":"The Pacific lies west of North and South America."},{"question":"Which continent contains the Sahara Desert?","options":["Australia","Africa","Europe","South America"],"correct_option_index":1,"explanation":"The Sahara spans much of North Africa."},{"question":"What is an archipelago?","options":["A group of islands","A single mountain","A type of desert","A wide river"],"correct_option_index":0,"explanation":"An archipelago consists of multiple islands."},{"question":"Why do coastal regions often experience sea breezes during the day?","options":["The sea stops Earth''s rotation","Clouds always move south","Mountains create all wind","Land heats faster than the sea"],"correct_option_index":3,"explanation":"Differences in heating create pressure and airflow patterns."},{"question":"What causes day and night on Earth?","options":["Earth''s distance changing each hour","Seasonal rainfall","Earth''s rotation","The Moon covering the Sun daily"],"correct_option_index":2,"explanation":"Earth rotates on its axis, turning places toward and away from the Sun."},{"question":"Which geographic feature is formed where a river deposits sediment near its mouth?","options":["Canyon","Delta","Glacier","Volcano"],"correct_option_index":1,"explanation":"River sediment can build a delta near the river mouth."},{"question":"Which renewable resource is strongly linked to windy coastal sites?","options":["Wind energy","Coal mining","Crude oil extraction","Peat burning"],"correct_option_index":0,"explanation":"Coastal winds can drive wind turbines where suitable."},{"question":"What is the main purpose of contour lines on a map?","options":["Show internet speed","Mark languages spoken","List historical events","Show elevation and terrain shape"],"correct_option_index":3,"explanation":"Contour lines join points of equal elevation."},{"question":"Why are mangroves valuable along tropical coasts?","options":["They create mountain peaks","They eliminate every storm","They help protect shorelines and support habitats","They remove all tides"],"correct_option_index":2,"explanation":"Mangroves can reduce erosion and provide wildlife habitat."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000009","title":"Computing, Coding & AI Thinking","subject":"Computing","grade_level":"Year 7","language":"en","description":"20 original questions about algorithms, coding concepts, data and thoughtful AI use.","questions":[{"question":"What is an algorithm?","options":["A sequence of steps to solve a problem","A computer''s screen colour","A type of battery","A keyboard layout"],"correct_option_index":0,"explanation":"Algorithms describe ordered steps for completing a task."},{"question":"What does a loop do in a program?","options":["Deletes every file","Changes the screen size","Always stops the computer","Repeats instructions"],"correct_option_index":3,"explanation":"A loop executes a block multiple times."},{"question":"What does a variable store?","options":["Only pictures","A physical keyboard","A value that may change","A permanent computer case"],"correct_option_index":2,"explanation":"Variables hold data used by a program."},{"question":"Which symbol is often used for an assignment in many programming languages?","options":["@","=","?","#"],"correct_option_index":1,"explanation":"Many languages use an equals sign to assign a value, though syntax varies."},{"question":"What is a boolean value?","options":["True or false","Only positive numbers","A drawing format","A web address"],"correct_option_index":0,"explanation":"Boolean logic represents two truth values."},{"question":"What does debugging mean?","options":["Deleting a user''s account","Making the keyboard louder","Purchasing software","Finding and fixing program errors"],"correct_option_index":3,"explanation":"Debugging investigates why code behaves incorrectly."},{"question":"Which data type best represents a person''s age in whole years?","options":["Audio file","Colour gradient","Integer","Image"],"correct_option_index":2,"explanation":"An integer represents a whole number."},{"question":"What is a conditional statement?","options":["A special mouse","Code that chooses an action based on a condition","A list of unrelated emojis","A permanent hardware component"],"correct_option_index":1,"explanation":"Conditionals allow different paths based on true or false checks."},{"question":"What is a function in programming?","options":["A reusable block of instructions","A kind of electricity bill","A computer brand","A printed receipt"],"correct_option_index":0,"explanation":"Functions group instructions for reuse."},{"question":"What is the purpose of testing software?","options":["To guarantee zero future problems","To avoid understanding the design","To remove all users","To check expected and unexpected behaviour"],"correct_option_index":3,"explanation":"Tests find regressions and unexpected behaviour before release."},{"question":"What is training data used for in machine learning?","options":["Replacing the operating system","Building a keyboard","Helping a model learn patterns","Powering a monitor"],"correct_option_index":2,"explanation":"Training algorithms learn statistical patterns from examples."},{"question":"Why should an AI answer be checked?","options":["Every AI answer is a legal document","AI can confidently produce incorrect information","AI never makes mistakes","AI responses are always official"],"correct_option_index":1,"explanation":"Model outputs can be inaccurate or fabricated."},{"question":"What is an example of personal data?","options":["A student''s full home address","A generic multiplication table","A fictional planet name","A random colour palette"],"correct_option_index":0,"explanation":"A home address can identify or locate someone."},{"question":"What does encryption help protect?","options":["The weight of a laptop","Screen brightness","The length of a lesson","Information from unauthorized reading"],"correct_option_index":3,"explanation":"Encryption makes data unreadable without the appropriate key."},{"question":"Which approach makes a program easier to maintain?","options":["Remove all tests","Repeat identical code everywhere","Use clear names and small functions","Keep every variable named x"],"correct_option_index":2,"explanation":"Readable modules make software easier to understand and revise."},{"question":"What is a database?","options":["A plastic computer case","A structured system for storing and retrieving data","A type of USB cable","A screen resolution"],"correct_option_index":1,"explanation":"Databases organise and query stored information."},{"question":"What is an API?","options":["An interface through which software components communicate","A replacement for every password","A computer monitor size","A school timetable"],"correct_option_index":0,"explanation":"An API defines ways programs request and exchange information."},{"question":"Why is input validation important?","options":["It makes all inputs trusted automatically","It turns photos into text","It replaces backups","It checks whether supplied values meet expected rules"],"correct_option_index":3,"explanation":"Validation rejects malformed or unacceptable data."},{"question":"What is rate limiting intended to do?","options":["Generate every question automatically","Disable all students","Restrict excessive requests to a service","Make every password shorter"],"correct_option_index":2,"explanation":"Rate limiting reduces overload and some forms of abuse."},{"question":"Which is a good way to build safer classroom software?","options":["Disable error handling","Test permissions using accounts with different roles","Trust any button click as authorization","Store secret keys in HTML"],"correct_option_index":1,"explanation":"Role-separated testing checks that unauthorized users cannot gain access."}]},{"id":"c8202611-05a0-4a9b-9f00-000000000010","title":"Real-World Maths: Data & Decisions","subject":"Mathematics","grade_level":"Year 6","language":"en","description":"20 reasoning-focused word problems about money, charts, measurement and percentage.","questions":[{"question":"A notebook costs RM8. You buy three. What is the total cost?","options":["RM11","RM16","RM32","RM24"],"correct_option_index":3,"explanation":"Three notebooks cost 3 × RM8 = RM24."},{"question":"A bus has 42 passengers. 15 get off. How many remain?","options":["25","37","27","57"],"correct_option_index":2,"explanation":"42 − 15 = 27 passengers."},{"question":"A class of 30 students has 18 girls. What fraction of the class is girls in simplest form?","options":["5/3","3/5","18/5","2/5"],"correct_option_index":1,"explanation":"18/30 simplifies to 3/5."},{"question":"A shop reduces RM50 by 10%. What is the new price?","options":["RM45","RM40","RM55","RM49"],"correct_option_index":0,"explanation":"10% of RM50 is RM5; RM50 − RM5 = RM45."},{"question":"A rectangle is 8 cm long and 5 cm wide. What is its area?","options":["26 cm²","13 cm²","80 cm²","40 cm²"],"correct_option_index":3,"explanation":"Area equals length × width = 8 × 5 = 40 cm²."},{"question":"A 2-litre bottle is shared equally into four cups. How much is in each cup?","options":["750 mL","200 mL","500 mL","250 mL"],"correct_option_index":2,"explanation":"2 L = 2000 mL; 2000 ÷ 4 = 500 mL."},{"question":"Six test scores are 5, 6, 7, 8, 9, 10. What is their mean?","options":["9","7.5","7","8"],"correct_option_index":1,"explanation":"The sum is 45; the mean is 45 ÷ 6 = 7.5."},{"question":"A cyclist rides 12 km in one hour at a steady speed. How far in 3 hours?","options":["36 km","24 km","15 km","48 km"],"correct_option_index":0,"explanation":"Distance is 12 × 3 = 36 km."},{"question":"What is 0.75 as a fraction in simplest form?","options":["7/5","1/4","4/3","3/4"],"correct_option_index":3,"explanation":"0.75 equals 75/100, which simplifies to 3/4."},{"question":"A bag contains 4 red and 6 blue marbles. What is the probability of picking red?","options":["3/5","1/4","2/5","4/6"],"correct_option_index":2,"explanation":"4 out of 10 marbles are red, so 4/10 = 2/5."},{"question":"What is the perimeter of a square with side 7 cm?","options":["21 cm","28 cm","49 cm","14 cm"],"correct_option_index":1,"explanation":"Four sides of 7 cm give 4 × 7 = 28 cm."},{"question":"A recipe uses 200 g of flour for 4 muffins. How much flour for 10 muffins at the same rate?","options":["500 g","400 g","600 g","800 g"],"correct_option_index":0,"explanation":"Each muffin needs 50 g; 10 need 500 g."},{"question":"What is the next number in 4, 9, 14, 19, ...?","options":["23","25","29","24"],"correct_option_index":3,"explanation":"Each term increases by 5."},{"question":"A train leaves at 14:20 and arrives at 15:05. How long is the journey?","options":["55 minutes","75 minutes","45 minutes","35 minutes"],"correct_option_index":2,"explanation":"From 14:20 to 15:00 is 40 min, plus 5 min."},{"question":"If 25% of a class is absent and the class has 32 students, how many are absent?","options":["16","8","6","12"],"correct_option_index":1,"explanation":"25% is one quarter; 32 ÷ 4 = 8."},{"question":"A box holds 12 pencils. How many boxes are needed for 70 pencils?","options":["6","5","7","8"],"correct_option_index":0,"explanation":"Five boxes hold only 60; six hold 72."},{"question":"What is 3/8 + 2/8?","options":["5/16","1/8","6/8","5/8"],"correct_option_index":3,"explanation":"Add numerators when denominators match: 3/8 + 2/8 = 5/8."},{"question":"A tank has 18 L, and 2.5 L is used. How much remains?","options":["14.5 L","20.5 L","15.5 L","16.5 L"],"correct_option_index":2,"explanation":"18 − 2.5 = 15.5 L."},{"question":"A map uses 1 cm to represent 5 km. How far is 4 cm on the map?","options":["25 km","20 km","9 km","15 km"],"correct_option_index":1,"explanation":"4 × 5 km = 20 km."},{"question":"The prices RM7, RM9, RM11, RM13, RM15 are recorded. What is their median?","options":["RM11","RM9","RM13","RM10"],"correct_option_index":0,"explanation":"The middle value of the five sorted prices is RM11."}]}]'::jsonb AS packs),
 expanded AS (
  SELECT p.value AS pack,q.value AS item,(q.ordinality-1)::integer AS position
  FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.packs) AS p(value)
  CROSS JOIN LATERAL jsonb_array_elements(p.value->'questions') WITH ORDINALITY AS q(value,ordinality)
 )
INSERT INTO questions (quiz_set_id,position,question,choices,correct_index,explanation)
SELECT (e.pack->>'id')::uuid,e.position,e.item->>'question',e.item->'options',
 (e.item->>'correct_option_index')::smallint,e.item->>'explanation'
FROM expanded e JOIN quiz_sets s
 ON s.id=(e.pack->>'id')::uuid
 AND s.title=e.pack->>'title' AND s.status='published' AND s.owner_user_id IS NULL
WHERE NOT EXISTS (SELECT 1 FROM questions old WHERE old.quiz_set_id=s.id AND old.position=e.position);
DO $zokivo$
DECLARE total_sets integer; total_questions integer; partial_sets integer;
BEGIN
 SELECT count(*) INTO total_sets FROM quiz_sets WHERE id IN ('c8202611-05a0-4a9b-9f00-000000000001'::uuid,'c8202611-05a0-4a9b-9f00-000000000002'::uuid,'c8202611-05a0-4a9b-9f00-000000000003'::uuid,'c8202611-05a0-4a9b-9f00-000000000004'::uuid,'c8202611-05a0-4a9b-9f00-000000000005'::uuid,'c8202611-05a0-4a9b-9f00-000000000006'::uuid,'c8202611-05a0-4a9b-9f00-000000000007'::uuid,'c8202611-05a0-4a9b-9f00-000000000008'::uuid,'c8202611-05a0-4a9b-9f00-000000000009'::uuid,'c8202611-05a0-4a9b-9f00-000000000010'::uuid) AND status='published' AND owner_user_id IS NULL;
 SELECT count(*) INTO total_questions FROM questions WHERE quiz_set_id IN ('c8202611-05a0-4a9b-9f00-000000000001'::uuid,'c8202611-05a0-4a9b-9f00-000000000002'::uuid,'c8202611-05a0-4a9b-9f00-000000000003'::uuid,'c8202611-05a0-4a9b-9f00-000000000004'::uuid,'c8202611-05a0-4a9b-9f00-000000000005'::uuid,'c8202611-05a0-4a9b-9f00-000000000006'::uuid,'c8202611-05a0-4a9b-9f00-000000000007'::uuid,'c8202611-05a0-4a9b-9f00-000000000008'::uuid,'c8202611-05a0-4a9b-9f00-000000000009'::uuid,'c8202611-05a0-4a9b-9f00-000000000010'::uuid);
 SELECT count(*) INTO partial_sets FROM (
  SELECT quiz_set_id,count(*) n FROM questions WHERE quiz_set_id IN ('c8202611-05a0-4a9b-9f00-000000000001'::uuid,'c8202611-05a0-4a9b-9f00-000000000002'::uuid,'c8202611-05a0-4a9b-9f00-000000000003'::uuid,'c8202611-05a0-4a9b-9f00-000000000004'::uuid,'c8202611-05a0-4a9b-9f00-000000000005'::uuid,'c8202611-05a0-4a9b-9f00-000000000006'::uuid,'c8202611-05a0-4a9b-9f00-000000000007'::uuid,'c8202611-05a0-4a9b-9f00-000000000008'::uuid,'c8202611-05a0-4a9b-9f00-000000000009'::uuid,'c8202611-05a0-4a9b-9f00-000000000010'::uuid)
  GROUP BY quiz_set_id HAVING count(*) <> 20
 ) x;
 IF total_sets <> 10 OR total_questions <> 200 OR partial_sets <> 0 THEN
  RAISE EXCEPTION 'ZoKivo curated library integrity mismatch: sets %, questions %, irregular sets %',total_sets,total_questions,partial_sets;
 END IF;
END
$zokivo$;
COMMIT;
